   261→				if (!e.target || !(e.target.result instanceof ArrayBuffer)) return;
   262→				const pdf = await pdfjs.getDocument({ data: new Uint8Array(e.target.result) }).promise;
   263→
   264→				for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
   265→					const page = await pdf.getPage(pageNum);
   266→					const viewport = page.getViewport({ scale: 1.5 });
